// The resolved sequences keep the input's own extension, with any '.gz' stripped first so a
// compressed input is not written as "*.resolved.gz". Falls back to 'fasta' when the input has
// no extension at all (e.g. a download URL with no filename suffix), which would otherwise
// produce a malformed "*.resolved." name matching nothing.
def resolvedExtension(sequences) {
    def stem = sequences.name.endsWith('.gz') ? sequences.baseName : sequences.name
    stem.contains('.') ? stem.substring(stem.lastIndexOf('.') + 1) : 'fasta'
}

process CUSTOM_RESOLVETAXONOMY {
    tag "$meta.id"
    label 'process_low'

    conda "${moduleDir}/environment.yml"
    container "${workflow.containerEngine in ['singularity', 'apptainer'] && !task.ext.singularity_pull_docker_container
        ? 'https://community-cr-prod.seqera.io/docker/registry/v2/blobs/sha256/07/07d96b48e6ed9c1b07580549220facb20a0f01f0e135a7714954220d99b2588d/data'
        : 'community.wave.seqera.io/library/biopython_python:1ed2958705acf8e6'}"

    input:
    tuple val(meta), path(taxonomy), path(sequences), val(taxonomy_required)

    output:
    tuple val(meta), path("*.resolved.tax"),                                  emit: taxonomy
    tuple val(meta), path("*.resolved.${resolvedExtension(sequences)}"),      emit: sequences
    tuple val(meta), path("*.warnings.txt"),                                  emit: warnings
    tuple val("${task.process}"), val('biopython'), eval("python3 -c 'import Bio; print(Bio.__version__)'"), emit: versions_biopython, topic: versions

    when:
    task.ext.when == null || task.ext.when

    script:
    def prefix = task.ext.prefix ?: "${meta.id}"
    def ext = resolvedExtension(sequences)
    // Nextflow stages an absent optional path(taxonomy) as an empty list -- falsy in
    // Groovy -- rather than as a file, so this correctly distinguishes "no taxonomy
    // file given" from a real one, without ever interpolating the literal text "[]"
    // into the command line.
    def taxonomy_in = taxonomy ? "${taxonomy}" : ''
    """
    python3 - "${taxonomy_in}" "${sequences}" "${taxonomy_required}" "${prefix}.resolved.tax" "${prefix}.resolved.${ext}" "${prefix}.warnings.txt" << 'PYEOF'
import gzip
import sys
from Bio import SeqIO

taxonomy_in, sequences_in, taxonomy_required, taxonomy_out, sequences_out, warnings_out = sys.argv[1:7]
taxonomy_required = taxonomy_required == 'true'

def opentext(path):
    # Sniffed from the magic bytes rather than the suffix: an input can arrive with any
    # name, and reading a gzip member as text yields mojibake instead of an error.
    with open(path, 'rb') as fh:
        compressed = fh.read(2) == b'\\x1f\\x8b'
    return gzip.open(path, 'rt') if compressed else open(path)

# Format sniffed from content (FASTA, Clustal or PHYLIP -- sequences can be any of
# these, depending on the caller).
with opentext(sequences_in) as fh:
    first_line = next((l.strip() for l in fh if l.strip()), '')
if first_line.startswith('>'):
    sequences_format = 'fasta'
elif first_line.upper().startswith('CLUSTAL'):
    sequences_format = 'clustal'
else:
    sequences_format = 'phylip-relaxed'

with opentext(sequences_in) as fh:
    records = list(SeqIO.parse(fh, sequences_format))
warnings = []

def embedded_taxonomy(record):
    # record.description is the *whole* header line (id + any trailing text);
    # record.id is just its first token -- GTDB's own single-file convention puts
    # the taxonomy string right after the id, space-separated.
    return record.description[len(record.id):].strip()

if taxonomy_in:
    # An explicit taxonomy file always wins. Warn (not fail) rather than silently
    # using the wrong source if the sequences also happen to carry embedded text.
    if any(embedded_taxonomy(record) for record in records):
        warnings.append(
            'An explicit taxonomy file was provided; ignoring embedded taxonomy '
            'text found in sequence record headers.'
        )
    with opentext(taxonomy_in) as fh_in, open(taxonomy_out, 'w') as fh_out:
        fh_out.write(fh_in.read())
else:
    missing = [record.id for record in records if not embedded_taxonomy(record)]
    if missing and taxonomy_required:
        sys.exit(
            'No taxonomy file was provided, and these records have no embedded '
            'taxonomy in their header either: ' + ', '.join(missing)
        )
    if missing:
        warnings.append(
            'No taxonomy file was provided; records with no embedded taxonomy in '
            'their header are omitted from the resolved taxonomy: ' + ', '.join(missing)
        )
    with open(taxonomy_out, 'w') as fh:
        for record in records:
            tax = embedded_taxonomy(record)
            if tax:
                print(f"{record.id}\\t{tax}", file=fh)

# Always strip headers down to a bare id -- some downstream tools keep the whole
# header line as the sequence/leaf name rather than just the first token.
for record in records:
    record.description = record.id
SeqIO.write(records, sequences_out, sequences_format)

with open(warnings_out, 'w') as fh:
    for warning in warnings:
        print(warning, file=fh)
PYEOF
    """

    stub:
    def prefix = task.ext.prefix ?: "${meta.id}"
    def ext = resolvedExtension(sequences)
    """
    touch ${prefix}.resolved.tax ${prefix}.resolved.${ext} ${prefix}.warnings.txt
    """
}

nextflow_process {

    name "Test Process CUSTOM_RESOLVETAXONOMY"
    script "../main.nf"
    process "CUSTOM_RESOLVETAXONOMY"

    tag "modules"
    tag "modules_nfcore"
    tag "custom"
    tag "custom/resolvetaxonomy"

    test("embedded taxonomy, no external file, required") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    [],
                    file(params.modules_testdata_base_path + 'generic/fasta/resolvetaxonomy_embedded.fasta', checkIfExists: true),
                    true,
                ]
                """
            }
        }

        then {
            assert process.success

            def taxonomy = path(process.out.taxonomy[0][1]).text
            def sequences = path(process.out.sequences[0][1]).text

            assertAll(
                { assert taxonomy.contains('SeqA\tBacteria;PhylumA;ClassA;OrderA;FamilyA;GenusA;SpeciesA') },
                { assert taxonomy.contains('SeqB\tBacteria;PhylumA;ClassB;OrderB;FamilyB;GenusB;SpeciesB') },
                // Headers stripped down to a bare id -- no leftover taxonomy text that
                // could later be mistaken for part of the sequence name downstream.
                { assert sequences.contains('>SeqA\n') },
                { assert sequences.contains('>SeqB\n') },
                { assert !sequences.contains('Bacteria') },
                { assert path(process.out.warnings[0][1]).text.trim().isEmpty() },
                { assert process.out.versions_biopython },
            )
        }

    }

    test("external taxonomy file wins, warns on ignored embedded text") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'generic/tax/resolvetaxonomy_override.tax', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'generic/fasta/resolvetaxonomy_embedded.fasta', checkIfExists: true),
                    true,
                ]
                """
            }
        }

        then {
            assert process.success

            def taxonomy = path(process.out.taxonomy[0][1]).text
            def sequences = path(process.out.sequences[0][1]).text

            assertAll(
                // The explicit file's (distinguishable) content wins...
                { assert taxonomy.contains('SeqA\tArchaea;OverridePhylum;OverrideClass') },
                { assert taxonomy.contains('SeqB\tArchaea;OverridePhylum;OverrideClass2') },
                // ...not the Bacteria;... lineage embedded in the FASTA headers.
                { assert !taxonomy.contains('Bacteria') },
                { assert sequences.contains('>SeqA\n') },
                { assert !sequences.contains('Bacteria') },
                // Ignored, not silently used -- a warning is reported.
                { assert path(process.out.warnings[0][1]).text.toLowerCase().contains('ignoring') },
            )
        }

    }

    test("external taxonomy file, no embedded text, no warning") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'generic/tax/resolvetaxonomy_plain.tax', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'generic/fasta/resolvetaxonomy_plain.fasta', checkIfExists: true),
                    true,
                ]
                """
            }
        }

        then {
            assert process.success

            def taxonomy = path(process.out.taxonomy[0][1]).text

            assertAll(
                { assert taxonomy.contains('SeqGood1\tBacteria;PhylumA;ClassA') },
                { assert path(process.out.warnings[0][1]).text.trim().isEmpty() },
            )
        }

    }

    test("neither taxonomy file nor embedded text, required, fails clearly") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    [],
                    file(params.modules_testdata_base_path + 'generic/fasta/resolvetaxonomy_plain.fasta', checkIfExists: true),
                    true,
                ]
                """
            }
        }

        then {
            assert !process.success
            assert (process.stdout + process.stderr).join('\n').contains('taxonomy file')
        }

    }

    test("neither taxonomy file nor embedded text, not required, warns and continues") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    [],
                    file(params.modules_testdata_base_path + 'generic/fasta/resolvetaxonomy_plain.fasta', checkIfExists: true),
                    false,
                ]
                """
            }
        }

        then {
            assert process.success

            def taxonomy = path(process.out.taxonomy[0][1]).text

            assertAll(
                { assert taxonomy.trim().isEmpty() },
                { assert path(process.out.warnings[0][1]).text.contains('SeqGood1') },
                { assert path(process.out.warnings[0][1]).text.contains('SeqGood2') },
            )
        }

    }

    test("partial embedded taxonomy, not required, drops records with no taxonomy") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    [],
                    file(params.modules_testdata_base_path + 'generic/fasta/resolvetaxonomy_partial.fasta', checkIfExists: true),
                    false,
                ]
                """
            }
        }

        then {
            assert process.success

            def taxonomy = path(process.out.taxonomy[0][1]).text

            assertAll(
                { assert taxonomy.contains('SeqC\tBacteria;PhylumA;ClassA;OrderA;FamilyA;GenusA;SpeciesC') },
                { assert !taxonomy.contains('SeqD') },
                { assert path(process.out.warnings[0][1]).text.contains('SeqD') },
            )
        }

    }

    test("sequences file with no extension at all") {

        when {
            process {
                """
                def noExtPath = java.nio.file.Files.createTempDirectory('resolvetaxonomy_test').resolve('resolvetaxonomy_embedded')
                noExtPath.toFile().text = file(params.modules_testdata_base_path + 'generic/fasta/resolvetaxonomy_embedded.fasta', checkIfExists: true).text

                input[0] = [
                    [ id:'test' ],
                    [],
                    file(noExtPath.toString()),
                    true,
                ]
                """
            }
        }

        then {
            assert process.success

            def sequences = path(process.out.sequences[0][1])

            assertAll(
                // Falls back to '.resolved.fasta', not a malformed '.resolved.' with
                // no extension.
                { assert sequences.toFile().name.endsWith('.resolved.fasta') },
                { assert sequences.text.contains('>SeqA\n') },
            )
        }

    }

    // Both inputs are opened through Python's gzip, sniffed on the magic bytes. The resolved
    // sequences keep the real format in their name: '.resolved.fasta', not '.resolved.gz'.
    test("gzipped sequences and taxonomy") {

        when {
            process {
                """
                def tmp = java.nio.file.Files.createTempDirectory('resolvetaxonomy_gz')

                def gzippedTax = tmp.resolve('resolvetaxonomy_plain.tax.gz')
                new java.util.zip.GZIPOutputStream(gzippedTax.toFile().newOutputStream()).withStream { out ->
                    out << file(params.modules_testdata_base_path + 'generic/tax/resolvetaxonomy_plain.tax', checkIfExists: true).bytes
                }

                def gzippedFasta = tmp.resolve('resolvetaxonomy_plain.fasta.gz')
                new java.util.zip.GZIPOutputStream(gzippedFasta.toFile().newOutputStream()).withStream { out ->
                    out << file(params.modules_testdata_base_path + 'generic/fasta/resolvetaxonomy_plain.fasta', checkIfExists: true).bytes
                }

                input[0] = [
                    [ id:'test' ],
                    file(gzippedTax.toString()),
                    file(gzippedFasta.toString()),
                    true,
                ]
                """
            }
        }

        then {
            assert process.success

            def sequences = path(process.out.sequences[0][1])

            assertAll(
                // The same result as the uncompressed run above, not an empty or partial one.
                { assert path(process.out.taxonomy[0][1]).text.contains('SeqGood1\tBacteria;PhylumA;ClassA') },
                { assert path(process.out.warnings[0][1]).text.trim().isEmpty() },
                // '.resolved.fasta', not '.resolved.gz'.
                { assert sequences.toFile().name.endsWith('.resolved.fasta') },
                { assert sequences.text.startsWith('>') },
            )
        }

    }

    test("embedded taxonomy - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    [],
                    file(params.modules_testdata_base_path + 'generic/fasta/resolvetaxonomy_embedded.fasta', checkIfExists: true),
                    true,
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(process.out).match() }
            )
        }

    }

}
